  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sculpted Squad - Sculpted by Aimee''s application-based creator programme powered by Duel (apply via sculptedbyaimee.com)', null, 'https://www.duel.tech/sculpted-by-aimee', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.duel.tech/sculpted-by-aimee', 'listing', 'ugc_collab', 'Duel''s case study documents Sculpted by Aimee''s own creator programme, the Sculpted Squad: an application-based, tiered programme for social creators and micro-influencers in its customer base, where members complete tasks and ''unlock commission opportunities, discounts, product vouchers as well as other rewards'', tracking earned commission in their dashboard; over 1,000 members joined across the EU and UK in its first month.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.duel.tech/sculpted-by-aimee', 'listing', 'general', 'The same case study states Sculpted by Aimee is ''a rapidly growing cosmetics brand founded in 2016 by Makeup Artist Aimee Connolly'' with an ethos of making makeup easier.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/sculptedbyaimee-com-affiliate-program', 'listing', 'compensation', 'The Sculpted Squad''s commission rates are not published (commission unlocks by tier alongside product vouchers), and Shopper separately lists a US affiliate payout of 2-3.33% without naming its network - so commission_rate is recorded as null. No earnings-cap statement appears in any fetched source, so the cap is unknown; the programme''s 1,000+ first-month members are thousands-scale, not low-saturation evidence, so saturation is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 6, 6, 7, 4, '{"compensation": "Commission is earned inside the Squad but rates are unpublished and mixed with product-voucher rewards; a conflicting 2-3.33% US figure is reported by Shopper - no rate recorded.", "contact_access": "Application runs through the brand''s own site; no public partnerships email found - below mid-range.", "credibility": "Rapidly growing brand founded in 2016, stocked across Ireland and the UK, with 1,000+ programme members in its first month.", "niche_fit": "Creator-native Irish makeup brand whose whole model is built around social creators and micro-influencers.", "opportunity_availability": "Application-based and aimed at existing customers/fans rather than fully open, so availability scores below open network programmes.", "ugc_evidence": "A dedicated, documented creator programme (Sculpted Squad) with tasks, tiers, brand-channel features and PR event invites - strong structured UGC evidence."}'::jsonb);
