  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cuelinks.com/blog/top-beauty-skincare-affiliate-programs-india/', 'listing', 'compensation', 'Cuelinks'' Indian beauty affiliate roundup lists Bella Vita Organic at up to 20.25% commission with a 30-day cookie (noting campaigns may pause), and MonetizeDeal likewise lists up to 18% - the 18% flat EarnKaro rate is recorded, with the higher network figure documented as a conflict.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://earnkaro.com/blog/bella-vita-affiliate-program/', 'listing', 'compensation', 'EarnKaro''s benefits copy says ''There is no limit to how much you can earn'', but its own FAQ on the same page states affiliates ''can earn up to Rs 10,000 per month'' - because the same fetched source contradicts itself, the explicit-no-cap standard is not met and the cap is honestly recorded as unknown. No absolute creator-count evidence is published, so saturation is also unknown.', 'needs_review', now());
