  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/brands/hurom/affiliate-program', 'listing', 'compensation', 'Shopper lists the Hurom payout at up to 10%, consistent with the top of the reported range, but no fetched source publishes one fixed rate - so commission_rate is null with the 5-10% range documented.', 'needs_review', now());
