  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 6, 8, 5, '{"compensation": "Reported 5-10% range on premium-priced juicers, but no single fixed rate is published, so the rate is honestly unrecorded.", "contact_access": "Own affiliate page exists but renders dynamically; no published affiliate email found.", "credibility": "The original slow-juicer brand with 50+ years of research and global retail presence.", "niche_fit": "Premium juicers are a staple of wellness, kitchen and morning-routine creator content.", "opportunity_availability": "Open enrollment via ShareASale and the brand''s own affiliate page.", "ugc_evidence": "Program is marketed to influencers and content creators through creator-focused directories."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Snapmaker', 'https://www.snapmaker.com', 'Shenzhen-based maker technology company selling modular 3-in-1 machines that combine 3D printing, laser engraving/cutting and CNC carving, plus dedicated laser and printer models, through its own online store.', 'China', 'published') returning id into bid;
