  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.snapmaker.com/en-GB/referral-program/.', 'https://www.snapmaker.com/en-GB/referral-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Snapmaker Referral Program + Affiliate Program (application-based)', 'https://www.snapmaker.com/en-GB/referral-program/', 'https://www.snapmaker.com/en-GB/referral-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.snapmaker.com/en-GB/referral-program/', 'official_site', 'affiliate', 'Snapmaker''s own Referral Program page (fetched) is open to anyone: referrers earn cashback starting at 3% on machine orders, upgrading to 5% once referred sales reach $5,000, paid via PayPal or gift card, while buyers get 5% off machines; registration runs through Snapmaker''s affiliate portal.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.snapmaker.com/en-US/pages/snapmaker-rewards', 'official_site', 'affiliate', 'Snapmaker''s store FAQ directs creators to a separate application-based Affiliate Program ''to earn higher commission rates based on referral performance'' and publishes the marketing contact affiliate@snapmaker.com; a 2021 brand blog post put influencer affiliate commissions at 5-10%, but current rates are set on application, so the verified open-program base of 3% is recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.snapmaker.com/en-GB/referral-program/', 'official_site', 'affiliate', 'The referral page''s ''There is no limit to the number of friends you can refer'' is a statement about referral COUNT, not an earnings cap, so commission_cap stays ''unknown'' under the directory rule; no creator counts are published either.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 8, 11, 8, 4, '{"compensation": "Verified open program pays 3% cashback rising to 5% at $5,000 referred sales; the higher creator tier is application-based with unpublished rates.", "contact_access": "Published affiliate@snapmaker.com for creator partnerships plus info@snapmaker.com general contact.", "credibility": "Established maker brand known for record Kickstarter campaigns and modular machine design.", "niche_fit": "3-in-1 machines give makers three content categories (printing, laser, CNC) in one product line.", "opportunity_availability": "Referral program is open to everyone; the creator affiliate tier is application-based.", "ugc_evidence": "Brand runs creator feature stories and a dedicated influencer affiliate route, though terms are set privately."}'::jsonb);
